func TestGettersSensorPage(t *testing.T) {
	t.Run("GetItems", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &SensorPage{}
		var expected []*Sensor
		obj.Items = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetItems(), "getter should return the property value")
	})

	t.Run("GetItems_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &SensorPage{}
		obj.Items = nil

		// Act & Assert
		assert.Nil(t, obj.GetItems(), "getter should return nil when property is nil")
	})

	t.Run("GetItems_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *SensorPage
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetItems() // Should return zero value
	})

	t.Run("GetPageInfo", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &SensorPage{}
		var expected *PageInfo
		obj.PageInfo = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetPageInfo(), "getter should return the property value")
	})

	t.Run("GetPageInfo_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &SensorPage{}
		obj.PageInfo = nil

		// Act & Assert
		assert.Nil(t, obj.GetPageInfo(), "getter should return nil when property is nil")
	})

	t.Run("GetPageInfo_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *SensorPage
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetPageInfo() // Should return zero value
	})

}

